package components

import (
	"slices"
	"strings"
	"unicode"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// RowQuery names one row: the registry snapshot, the current context, the
// row's target as the registry knows it, the kinds the view can rerun (nil =
// all), and what the view observes on its own (container, agent).
type RowQuery struct {
	Runs     []jobs.Run     // any context; filtered here
	Failures []jobs.Failure // any context; filtered here
	Context  string
	Target   string
	Kinds    []jobs.Kind
	// Observed is the view's own state (Idle if none); ObservedText is its
	// sentence without glyph, shown when Observed wins or on an idle row.
	Observed     indicator.State
	ObservedText string
}

// RowActivity is what the first column and the footer say about one row.
type RowActivity struct {
	State  indicator.State
	Detail RowDetail
}

// RowState resolves the row's state without building any text. It is what the
// activity column calls; DescribeRow agrees with it by construction.
func RowState(q RowQuery) indicator.State { return resolveRow(q).state }

// DescribeRow resolves the row and builds its footer sentence.
func DescribeRow(q RowQuery) RowActivity {
	f := resolveRow(q)
	a := RowActivity{State: f.state}
	glyph := indicator.Glyph(f.state, true) // the footer glyph never blinks
	switch {
	case len(f.active) > 0:
		it := f.active[0]
		a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(it.Item.Name())}
		a.Detail.Lead = activeLead(f.state, it.Kind)
		a.Detail.Tail = maskedSuffix(f.failures)
	case len(f.failures) > 0:
		fl := f.failures[0]
		a.Detail = RowDetail{Glyph: glyph, Target: targetDisplay(failureName(fl)),
			Tail: failedTail(fl.Kind, fl.Detail) + maskedSuffix(f.failures[1:])}
	default:
		// No job and no failure: the view's own sentence. Idle shows it with no
		// glyph (D8); any other observed state shows it with the glyph.
		a.Detail = RowDetail{Lead: oneLine(q.ObservedText)}
		if f.state != indicator.Idle && a.Detail.Lead != "" {
			a.Detail.Glyph = glyph
		}
	}
	return a
}

// FailureEvent is the 3-second Error a view posts when an operation fails:
// "Failed to <kind> <target> — <cause>".
func FailureEvent(kind jobs.Kind, target, cause string) string {
	return "Failed to " + string(kind) + " " + targetDisplay(target) + causeSuffix(kind, cause)
}

// rowFacts is the single computation behind RowState and DescribeRow.
type rowFacts struct {
	state    indicator.State
	active   []jobs.Active  // running first, then queued
	failures []jobs.Failure // newest first; the winner when state is Failed
}

func resolveRow(q RowQuery) rowFacts {
	f := rowFacts{
		active:   jobs.ActiveOn(q.Runs, q.Context, q.Target, q.Kinds...),
		failures: jobs.FailuresOn(q.Failures, q.Context, q.Target, q.Kinds...),
	}
	slices.SortStableFunc(f.failures, func(a, b jobs.Failure) int { return b.At.Compare(a.At) })
	act := indicator.Activity{Failed: len(f.failures) > 0, Observed: q.Observed}
	for _, a := range f.active {
		act.Running = act.Running || a.Item.State == jobs.ItemRunning
		act.Queued = act.Queued || a.Item.State == jobs.ItemQueued
	}
	f.state = indicator.Resolve(act)
	return f
}

// failureName is the target as the launcher wants it printed.
func failureName(f jobs.Failure) string {
	if f.Display != "" {
		return f.Display
	}
	return f.Target
}

// targetDisplay folds the home directory of an absolute path; an image
// reference or a forge path is kept verbatim.
func targetDisplay(s string) string {
	s = oneLine(s)
	if isPathTarget(s) {
		return theme.FoldHome(s)
	}
	return s
}

// causeSuffix is " — <cause>", or "" when there is no cause. The cause is put
// on one line and loses a leading "<kind> failed" (the sentence says it) with
// the separator that follows it.
func causeSuffix(kind jobs.Kind, detail string) string {
	cause := oneLine(detail)
	if p := string(kind) + " failed"; len(cause) >= len(p) && strings.EqualFold(cause[:len(p)], p) {
		cause = cause[len(p):]
		if cause == "" || cause[0] == ' ' || cause[0] == ':' || cause[0] == '-' || strings.HasPrefix(cause, "—") {
			cause = strings.TrimSpace(trimSeparator(strings.TrimSpace(cause)))
		} else {
			cause = p + cause
		}
	}
	if cause == "" {
		return ""
	}
	return " — " + cause
}

// trimSeparator removes one leading "—", "--", "-" or ":".
func trimSeparator(s string) string {
	for _, sep := range []string{"—", "--", "-", ":"} {
		if rest, ok := strings.CutPrefix(s, sep); ok {
			return rest
		}
	}
	return s
}

// maxTextRunes bounds free text before it is processed.
const maxTextRunes = 512
	if isPathTarget(d.Target) && (pathRoom >= minPathCols || d.Tail != "") {
		full = d.head() + theme.ShortPath(d.Target, max(pathRoom, minPathCols)) + d.Tail
	}
	return theme.TruncateWidth(full, room)
}

// isPathTarget tells a filesystem path from an image reference such as
// "registry/ns/app:1.2", which ShortPath would mangle.
func isPathTarget(target string) bool {
	return filepath.IsAbs(target) || strings.HasPrefix(target, "~")
}

// RowStatusLine composes the footer line for a selected row: its detail, then
// the batch progress, on one line of at most width columns. The progress is
// what gives way last; the detail is dropped whole when fewer than
// minDetailCols are left for it (or fewer than it needs, if it is shorter).
func RowStatusLine(detail RowDetail, progress string, width int) string {
	switch {
	case width <= 0:
		return ""
	case detail.IsZero():
		return theme.TruncateWidth(progress, width)
	case progress == "":
		return detail.fit(width)
	}
	room := width - theme.StringWidth(rowSeparator) - theme.StringWidth(progress)
	if room < min(minDetailCols, theme.StringWidth(detail.String())) {
		return theme.TruncateWidth(progress, width)
	}
	return detail.fit(room) + rowSeparator + progress
}
// Style returns the style a level renders in.
func (l Level) Style() lipgloss.Style {
	switch l {
	case LevelError:
		return theme.FooterErrorStyle
	case LevelWarning:
		return theme.FooterWarnStyle
	default:
		return theme.FooterInfoStyle
	}
}

// Status is what a view derives on every frame: a progress line, a hint, or a
// table loading its rows. It carries no timer — a batch outlives the three
// seconds a message gets, which is why the sync and prune lines were rendered
// from state rather than assigned to footerInfo in the first place.
//
// It is a parameter of View rather than a field of FooterMessage because it is
// derived, not stored: containers' action line comes from BusyLabels(), which
// changes with no event to push it on.
type Status struct {
	Text string
	// Detail is what the selected row says about itself (RowStatusLine); Text
	// then becomes the batch progress after it. A detail with a glyph drops the
	// spinner: the row's own dot already moves.
	Detail RowDetail
	// Spinner prepends the current spinner frame — a table loading its rows.
	Spinner bool
	// Level colours the line, and the zero value is LevelInfo, so a status that
	// says nothing about it renders exactly as it always did.
	//
	// A derived state can be a failure as legitimately as it can be progress:
	// "Docker unreachable" is not an event that happened once, it is what is
	// true right now, and a message would expire after three seconds — which is
	// D47 in one field. It needs the colour of an error and the lifetime of a
	// state, and only Status can give it both.
	Level Level
}

// footerMsgSeq numbers messages so a timer can name the one it was started for.
var footerMsgSeq atomic.Uint64

// ClearFooterMsg expires the message identified by ID.
//
// The ID is what makes the type safe to share across packages. Two things would
// otherwise go wrong: a timer started by one view could clear the message of
// whichever view is active when it lands, and — the bug that was already
// present in all eight local implementations — a message set at t+2.9s was
// wiped at t+3s by its predecessor's timer.
type ClearFooterMsg struct{ ID uint64 }

package workspaces

import (
	"slices"
	"strconv"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/git"
	"github.com/anthnel/devdesk/internal/jobs"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
)

// This view's knowledge of what is running is a snapshot the router hands it,
// and nothing else (D1). It replaced three maps — scanningPaths, syncingPaths,
// deletingPaths — and the syncRun that counted a batch alongside them.
//
// What the three maps could not do is the whole point: they knew only what this
// view had started. A scan launched on the same repository from `:sec` was
// invisible to busy(), so the guard let a second one through and the two wrote
// the same cache entry. The registry is one bookkeeping, so the guard now
// answers for work started anywhere.

// scanRun builds the run behind S, A and ctrl+a. Label is what `:jobs` shows,
// and the directory being worked in is what identifies the batch to a human.
func (m Model) scanRun(targets []string) jobs.Run {
	return jobs.NewRun(jobs.KindScan, command.ViewWorkspaces, "", m.runLabel(), targets...)
}

func (m Model) syncRun(targets []string) jobs.Run {
	return jobs.NewRun(jobs.KindSync, command.ViewWorkspaces, "", m.runLabel(), targets...)
}

func (m Model) deleteRun(target string) jobs.Run {
	return jobs.NewRun(jobs.KindDelete, command.ViewWorkspaces, "", pathBaseName(target), target)
}

// runLabel names a batch by the directory it was launched in.
func (m Model) runLabel() string {
	if m.currentPath != "" {
		return pathBaseName(m.currentPath)
	}
	return pathBaseName(m.getExpandedWorkspacesDir())
}

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields, and there is nothing to reconcile: the snapshot replaces what was
// held rather than being merged into it.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.refreshRows()
	return m, nil
}

// handleFrameMsg takes the animation's frame: the blink phase, which the table
// reads at render, and the footer spinner. No row is rebuilt.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.table.SetBlinkPhase(msg.Blink)
	m.footer.SetSpinnerFrame(msg.RenderedFrame)
	return m, nil
}

// liveRuns returns the runs this view is showing: the ones still going, whatever
// view started them.
//
// Not filtered by origin — that is the point. A scan `:sec` launched on a
// repository listed here spins on its row, because it is the same repository
// and the same work.
func (m Model) liveRuns() []jobs.Run {
	return jobs.Unfinished(m.jobs)
}

// itemState returns where a target stands in the live runs of a kind, and
// whether it is there at all.
func (m Model) itemState(kind jobs.Kind, target string) (jobs.ItemState, bool) {
	for _, run := range m.liveRuns() {
		if run.Kind != kind {
			continue
		}
		for _, item := range run.Items {
			if item.Target == target && !item.State.Terminal() {
				return item.State, true
			}
		}
	}
	return "", false
}

// working reports whether a target is queued or running under any kind.
func (m Model) working(target string) bool {
	for _, run := range m.liveRuns() {
		for _, item := range run.Items {
			if item.Target == target && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// anyWorking reports whether anything at all is going, which is what decides
// whether the footer's progress line carries a spinner.
func (m Model) anyWorking() bool { return len(m.liveRuns()) > 0 }

// workingKind reports whether a target is queued or running under one kind.
func (m Model) workingKind(kind jobs.Kind, target string) bool {
	_, ok := m.itemState(kind, target)
	return ok
}

// scanning, syncing and deleting are the three readings the rows need. They
// replace the three maps one for one, and they read the same source.
func (m Model) scanning(path string) bool { return m.workingKind(jobs.KindScan, path) }
func (m Model) syncing(path string) bool  { return m.workingKind(jobs.KindSync, path) }
func (m Model) deleting(path string) bool { return m.workingKind(jobs.KindDelete, path) }

// runningKind reports whether a target is being worked on right now under one
// kind. A queued item does not count: only a running one holds a cell's text.
func (m Model) runningKind(kind jobs.Kind, target string) bool {
	state, ok := m.itemState(kind, target)
	return ok && state == jobs.ItemRunning
}

// ── The footer line (D9) ─────────────────────────────────────────────────────

// jobsStatusLine is what the footer says while work runs. The three forms and
// the reason for the third live with the shared implementation
// (components.JobsStatusLine) — the dashboard says the same sentence now, and
// two copies of a surrender would each be free to surrender differently.
func (m Model) jobsStatusLine() string {
	return sharedcomponents.JobsStatusLine(m.jobs, command.ViewWorkspaces)
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────
//
// The mapping lives here and not in the router: "a sync that was refused
// because the tree is dirty is a skip, and the reason is worth keeping" is this
// package's vocabulary, and a router that knew it would grow one branch per
// view.

// syncDetailUpdated marks the one settled outcome the item state cannot carry.
// A sync that fast-forwarded and one that had nothing to do are both done; the
// summary counts them apart, and this is the only thing that tells them apart.
const syncDetailUpdated = "updated"

func (m WorkspaceScanStartingMsg) Transition() jobs.Transition {
	// The cancel goes with the state that says the work started, which is the
	// only moment there is anything to stop (D7).
	return jobs.Transition{
		Kind: jobs.KindScan, Target: m.RepoPath,
		State: jobs.ItemRunning, Cancel: m.Cancel,
	}
}

func (m WorkspaceScanCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.RepoPath, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m WorkspaceSyncStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemRunning}
}

func (m WorkspaceSyncCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindSync, Target: m.RepoPath, State: jobs.ItemDone}
	switch {
	case m.Error != nil:
		t.State = jobs.ItemFailed
		t.Detail = "sync failed — check logs"
	case m.Outcome == git.SyncSkipped:
		// A refusal is not a failure: the fetch happened, the merge did not,
		// and the reason is what the summary names one repository by.
		t.State = jobs.ItemSkipped
		t.Detail = m.Reason
	case m.Outcome == git.SyncUpdated:
		t.Detail = syncDetailUpdated
	}
	return t
}

func (m EntryDeletedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindDelete, Target: m.Path, State: jobs.ItemDone}
	if m.Error != nil {
		t.State = jobs.ItemFailed
		t.Detail = "delete failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message this view emits can be applied
// to the registry. A message added without one would be routed, would update
// the view, and would leave its row spinning for the life of the view — which
// is precisely the failure the registry exists to remove.
var (
	_ jobs.Reporter = WorkspaceScanStartingMsg{}
	_ jobs.Reporter = WorkspaceScanCompleteMsg{}
	_ jobs.Reporter = WorkspaceSyncStartingMsg{}
	_ jobs.Reporter = WorkspaceSyncCompleteMsg{}
	_ jobs.Reporter = EntryDeletedMsg{}
)

// ── The sync summary ─────────────────────────────────────────────────────────

// syncSummary is what the footer says once a sync batch has settled.
//
// It is posted as a footer message rather than derived like the progress line,
// and the difference is Rule 128's own: progress is a state, which is why it
// cannot carry a timer, and an outcome is an event, which is exactly what a
// footer message is. The old code derived both from one struct because they
// shared a function; once progress comes from the registry, they stop needing
// to be the same thing.
func (m Model) syncSummary(run jobs.Run) string {
	var updated, upToDate, skipped, failed int
	var firstSkipped, firstSkippedReason, firstFailed string

	for _, item := range run.Items {
		switch {
		case item.State == jobs.ItemFailed:
			failed++
			if firstFailed == "" {
				firstFailed = pathBaseName(item.Target)
			}
		case item.State == jobs.ItemSkipped:
			// A cancellation lands here too, and its Detail says so: the
			// registry writes "cancelled" on an item that never ran, which
			// reads correctly in "1 skipped (api: cancelled)".
			skipped++
			if firstSkipped == "" {
				firstSkipped = pathBaseName(item.Target)
				firstSkippedReason = item.Detail
			}
		case item.Detail == syncDetailUpdated:
			updated++
		default:
			upToDate++
		}
	}

	var parts []string
	if updated > 0 {
		parts = append(parts, sharedcomponents.Plural(updated, "repository", "repositories")+" updated")
	}
	if upToDate > 0 {
		parts = append(parts, strconv.Itoa(upToDate)+" up to date")
	}
	if skipped > 0 {
		parts = append(parts, strconv.Itoa(skipped)+" skipped ("+firstSkipped+": "+firstSkippedReason+")")
	}
	if failed > 0 {
		parts = append(parts, strconv.Itoa(failed)+" failed ("+firstFailed+") — check logs")
	}
	if m.syncMovedTags > 0 {
		parts = append(parts, sharedcomponents.Plural(m.syncMovedTags, "tag", "tags")+" moved ("+m.syncFirstMovedTag+")")
	}
	if m.syncUnreadable > 0 {
		parts = append(parts, sharedcomponents.Plural(m.syncUnreadable, "directory", "directories")+" unreadable — check logs")
	}
	if len(parts) == 0 {
		return "Nothing to sync"
	}
	return strings.Join(parts, " · ")
}
